// B3 artwork generated with imagegen and selected by the owner.
// Embedded so existing signed/checksummed source updaters deliver the icon
// without broadening ZIP extraction to any new executable/media file types.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
const ICON = Buffer.from('', 'base64');
export const ICON_SHA256 = 'b70a36d6ddd1b181d97bfd41fd37b1d1e1ea3e3be3014af2294b5abaf516cbfb';
export function launcherIconBytes() { return Buffer.from(ICON); }
export function materializeLauncherIcon(app) {
  const file = path.join(app, 'crew-b3-b70a36d6ddd1.ico');
  const current = fs.existsSync(file) ? crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex') : '';
  if (current !== ICON_SHA256) {
    fs.writeFileSync(file + '.next', ICON, { mode: 0o600 });
    fs.renameSync(file + '.next', file);
  }
  return file;
}
